    #[test]
    fn test_has_common_element() {
        let a: Vec<i32> = vec![];
        let b: Vec<i32> = vec![];
        assert!(!has_common_element(&a, &b));

        let a = vec![1, 2, 3];
        let b = vec![4, 5, 6];
        assert!(!has_common_element(&a, &b));

        let b = vec![3, 4, 5];
        assert!(has_common_element(&a, &b));

        let a = vec![10, 20, 30];
        let b = vec![5, 10, 15];
        assert!(has_common_element(&a, &b));

        // common at different positions
        let a = vec![7, 8, 9];
        let b = vec![9, 0, 1];
        assert!(has_common_element(&a, &b));
    }
